const config = readConfig();
const p1 = await probe("proxy");
const p2 = await probe("backend");
const p3 = await probe("configuredUpstream");
const result = {
  configuration: config,
  probes: {
    proxy: p1,
    backend: p2,
    configuredUpstream: p3
  },
  finding: p1.status === 502 ? "Proxy returns 502 Bad Gateway" : "Proxy operational"
};
console.log(JSON.stringify(result));

const cfg = readConfig();
const pRes = await probe("proxy");
const bRes = await probe("backend");
const uRes = await probe("configuredUpstream");
const mismatch = cfg.upstreamPort !== cfg.backendPort;
const finding = mismatch ? "Proxy configured upstream port does not match running backend port" : "Ports match";
const result = { config: cfg, proxy: pRes, backend: bRes, upstream: uRes, finding: finding };
console.log(JSON.stringify(result));
